// Combina el id de variante real + la ubicacion interna del deposito + la cantidad del plan.
const variant = $json;
const plan = $('Plan de stock').item.json;
const locField = $('Deposito (WH/Stock)').first().json.lot_stock_id;
const locationId = Array.isArray(locField) ? locField[0] : locField;
if (!locationId) throw new Error('No se pudo obtener lot_stock_id del deposito.');

const variantField = variant.product_variant_id;
const variantId = Array.isArray(variantField) ? variantField[0] : variantField;
if (!variantId) {
  throw new Error('No se pudo resolver product_variant_id para template ' + plan.templateId + ' (' + (variant.name||'') + ')');
}
return { json: { productId: variantId, qty: plan.qty, locationId, templateId: plan.templateId, nombre: variant.name } };
